INSERT OR IGNORE INTO courses (id,slug,title,description,source_language,target_language,status) VALUES ('course-a1-foundations','a1-foundations','A1 Foundations','Original CEFR-aligned beginner English course. Unit 1: first conversations.','fa','en','published');

INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u01-l01','course-a1-foundations','hello-and-introductions','Hello and Introductions','Greet people, introduce yourself, and ask someone''s name. CEFR A1: exchange simple personal information.','A1',1,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u01-l01-q01','a1-u01-l01','multiple_choice','Choose the best greeting for 9:00 a.m.','[{"id":"a","text":"Good morning"},{"id":"b","text":"Good night"},{"id":"c","text":"Goodbye"}]','a','Use Good morning in the morning.',1),
('a1-u01-l01-q02','a1-u01-l01','multiple_choice','Complete: I ___ Mina.','[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}]','a','With I, use am. The contraction is I''m.',2),
('a1-u01-l01-q03','a1-u01-l01','multiple_choice','Someone says Nice to meet you. Choose a natural reply.','[{"id":"a","text":"Nice to meet you, too."},{"id":"b","text":"I am twelve."},{"id":"c","text":"Good night morning."}]','a','Nice to meet you, too is a polite response.',3),
('a1-u01-l01-q04','a1-u01-l01','multiple_choice','Which question asks for a person''s name?','[{"id":"a","text":"What''s your name?"},{"id":"b","text":"Where are you from?"},{"id":"c","text":"How old are you?"}]','a','Ask What''s your name? to learn someone''s name.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u01-l01:v1','a1-u01-l01',1,'Hello and Introductions','Greet people, introduce yourself, and ask someone''s name. CEFR A1: exchange simple personal information.','A1',1,'draft',NULL);
