UPDATE lessons SET current_published_version_id='a1-u01-l01:v1' WHERE id='a1-u01-l01' AND EXISTS (SELECT 1 FROM lesson_versions WHERE id='a1-u01-l01:v1' AND status='published');

INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u01-l02','course-a1-foundations','personal-information','Personal Information','Ask and answer basic questions about age, hometown, and where someone lives. CEFR A1: give simple personal details.','A1',2,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u01-l02-q01','a1-u01-l02','multiple_choice','Choose the correct question about age.','[{"id":"a","text":"How old are you?"},{"id":"b","text":"How are you old?"},{"id":"c","text":"How many old are you?"}]','a','The standard question is How old are you?',1),
('a1-u01-l02-q02','a1-u01-l02','multiple_choice','Complete: I ___ in Baku.','[{"id":"a","text":"live"},{"id":"b","text":"lives"},{"id":"c","text":"living"}]','a','Use the base verb live with I.',2),
('a1-u01-l02-q03','a1-u01-l02','multiple_choice','Choose the correct answer to Where are you from?','[{"id":"a","text":"I''m from Azerbaijan."},{"id":"b","text":"I''m 21 years."},{"id":"c","text":"I live 21."}]','a','Use be + from + place to state origin.',3),
('a1-u01-l02-q04','a1-u01-l02','multiple_choice','Which word means the family name?','[{"id":"a","text":"surname"},{"id":"b","text":"age"},{"id":"c","text":"address"}]','a','Surname means family name or last name.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u01-l02:v1','a1-u01-l02',1,'Personal Information','Ask and answer basic questions about age, hometown, and where someone lives. CEFR A1: give simple personal details.','A1',2,'draft',NULL);
