UPDATE lesson_versions SET status='published',published_at=CURRENT_TIMESTAMP WHERE id='a1-u01-l02:v1' AND status='draft' AND (SELECT COUNT(*) FROM question_versions WHERE lesson_version_id='a1-u01-l02:v1')=4;
