INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u01-l03','course-a1-foundations','countries-and-nationalities','Countries and Nationalities','Name countries and nationalities and use be to describe where people are from. CEFR A1: identify origin.','A1',3,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u01-l03-q01','a1-u01-l03','multiple_choice','Complete: They ___ from Spain.','[{"id":"a","text":"are"},{"id":"b","text":"is"},{"id":"c","text":"am"}]','a','Use are with they.',1),
('a1-u01-l03-q02','a1-u01-l03','multiple_choice','What is the nationality adjective for Japan?','[{"id":"a","text":"Japanese"},{"id":"b","text":"Japanish"},{"id":"c","text":"Japanian"}]','a','The correct nationality adjective is Japanese.',2),
('a1-u01-l03-q03','a1-u01-l03','multiple_choice','Choose the correctly capitalized sentence.','[{"id":"a","text":"I am from Azerbaijan."},{"id":"b","text":"i am from azerbaijan."},{"id":"c","text":"I am from azerbaijan."}]','a','Capitalize I and country names.',3),
('a1-u01-l03-q04','a1-u01-l03','multiple_choice','He is Brazilian. He is from ___.','[{"id":"a","text":"Brazil"},{"id":"b","text":"Spanish"},{"id":"c","text":"Japan"}]','a','Brazilian is the nationality adjective; Brazil is the country.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u01-l03:v1','a1-u01-l03',1,'Countries and Nationalities','Name countries and nationalities and use be to describe where people are from. CEFR A1: identify origin.','A1',3,'draft',NULL);
