INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u01-l04','course-a1-foundations','numbers-and-contact-details','Numbers and Contact Details','Understand numbers 0–20 and ask for simple contact details. CEFR A1: exchange basic numerical information.','A1',4,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u01-l04-q01','a1-u01-l04','multiple_choice','Which number comes after twelve?','[{"id":"a","text":"thirteen"},{"id":"b","text":"thirty"},{"id":"c","text":"twenty"}]','a','Thirteen comes after twelve.',1),
('a1-u01-l04-q02','a1-u01-l04','multiple_choice','Choose the natural question.','[{"id":"a","text":"What''s your phone number?"},{"id":"b","text":"How much years are you?"},{"id":"c","text":"What phone you number?"}]','a','Use What''s your phone number?',2),
('a1-u01-l04-q03','a1-u01-l04','multiple_choice','Complete: I''m ___.','[{"id":"a","text":"eighteen"},{"id":"b","text":"eighteens"},{"id":"c","text":"eighteen years"}]','a','The natural pattern is I''m eighteen years old or simply I''m eighteen.',3),
('a1-u01-l04-q04','a1-u01-l04','multiple_choice','What does Can you repeat that? mean?','[{"id":"a","text":"Say it again, please."},{"id":"b","text":"Write your name."},{"id":"c","text":"Speak more quickly."}]','a','Use this phrase when you need to hear information again.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u01-l04:v1','a1-u01-l04',1,'Numbers and Contact Details','Understand numbers 0–20 and ask for simple contact details. CEFR A1: exchange basic numerical information.','A1',4,'draft',NULL);
