INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u01-l05','course-a1-foundations','classroom-english','Classroom English','Understand common classroom instructions and ask for help politely. CEFR A1: follow simple instructions and request clarification.','A1',5,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u01-l05-q01','a1-u01-l05','multiple_choice','Which is a polite request for repetition?','[{"id":"a","text":"Can you repeat that, please?"},{"id":"b","text":"Repeat now you."},{"id":"c","text":"You repeat me."}]','a','This is a polite and natural request.',1),
('a1-u01-l05-q02','a1-u01-l05','multiple_choice','Choose the classroom instruction.','[{"id":"a","text":"Open your book."},{"id":"b","text":"You are open book."},{"id":"c","text":"Opening your book are."}]','a','Use the imperative verb form for instructions.',2),
('a1-u01-l05-q03','a1-u01-l05','multiple_choice','Complete: I don''t ___.','[{"id":"a","text":"understand"},{"id":"b","text":"understands"},{"id":"c","text":"understanding"}]','a','After don''t, use the base verb.',3),
('a1-u01-l05-q04','a1-u01-l05','multiple_choice','What should you say when you need help?','[{"id":"a","text":"I have a question, please."},{"id":"b","text":"I question have."},{"id":"c","text":"Question I am."}]','a','I have a question is a natural way to ask for help.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u01-l05:v1','a1-u01-l05',1,'Classroom English','Understand common classroom instructions and ask for help politely. CEFR A1: follow simple instructions and request clarification.','A1',5,'draft',NULL);
